<script lang="ts">
	// @ts-expect-error — generated by Wails
	import { GetLanguages, SetSelectedLanguage } from '@wails/go/main/App.js';

	interface Language {
		code: string;
		name: string;
		locale: string;
	}

	let languages = $state<Language[]>([]);
	let selectedCode = $state<string>('en');
	let loading = $state(true);

	async function loadLanguages(): Promise<void> {
		try {
			languages = await GetLanguages();
			if (languages.length > 0) {
				selectedCode = languages[0].code;
			}
		} catch (err) {
			console.error('Failed to load languages:', err);
		} finally {
			loading = false;
		}
	}

	async function onLanguageChange(event: Event): Promise<void> {
		const target = event.target as HTMLSelectElement;
		selectedCode = target.value;
		try {
			await SetSelectedLanguage(selectedCode);
		} catch (err) {
			console.error('Failed to set language:', err);
		}
	}

	loadLanguages();
</script>

<div class="page">
	<h2>Welcome Page</h2>
	<p>This is page 1 of 5.</p>

	<div class="language-selector">
		<label for="language">Language:</label>
		{#if loading}
			<span class="loading-text">Loading...</span>
		{:else}
			<select id="language" value={selectedCode} oninput={onLanguageChange}>
				{#each languages as lang (lang.code)}
					<option value={lang.code}>{lang.name}</option>
				{/each}
			</select>
		{/if}
	</div>
</div>

